SELECT

FROM (
	SELECT 
	FROM message
	WHERE conversation_id = #{conversationId}
	ORDER BY created_at DESC

		LIMIT #{limit}

) t
ORDER BY t.created_at ASC

SELECT

FROM message
WHERE conversation_id = #{conversationId}
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT id, conversation_id, user_id, role, content, token_count, created_at
FROM (
	SELECT id, conversation_id, user_id, role, content, token_count, created_at
	FROM message
	WHERE user_id = #{userId}
	ORDER BY created_at DESC
	LIMIT #{limit}
) t
ORDER BY t.created_at ASC
